    screen.position.set(9.6, 1.0, 6.56); screen.rotation.x = -0.32; propsGroup.add(screen);
    const stool = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.34, 0.55, 12), new THREE.MeshLambertMaterial({ color: 0x3a4a41 }));
