Now the big game.js. Let me write it carefully.

```js
'use strict';

/* ── Audio ── */
const Sfx = (() => {
  let ctx = null, muted = localStorage.getItem('hydroharvest_muted') === '1';
  function unlock(){ if (!ctx) { try { ctx = new (window.AudioContext||window.webkitAudioContext)(); } catch{} } if (ctx && ctx.state==='suspended') ctx.resume(); }
  function tone(freq, dur, opts={}) {
    if (muted) return; unlock(); if (!ctx) return;
    const { type='sine', vol=0.06, delay=0, slide=null } = opts;
    const t0 = ctx.currentTime + delay;
    const osc = ctx.createOscillator(), g = ctx.createGain();
    osc.type = type; osc.frequency.setValueAtTime(freq, t0);
    if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(30,slide), t0+dur);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(vol, t0+0.012);
    g.gain.exponentialRampToValueAtTime(0.0001, t0+dur);
    osc.connect(g).connect(ctx.destination);
    osc.start(t0); osc.stop(t0+dur+0.02);
  }
  const play = name => {
    switch(name){
      case 'click': tone(760,.05,{type:'triangle',vol:.03}); break;
      case 'plant': tone(392,.1,{type:'sine',vol:.05}); tone(523,.12,{delay:.07,vol:.05}); break;
      case 'harvest': [523,659,784].forEach((f,i)=>tone(f,.16,{delay:i*.08,vol:.055})); break;
      case 'sell': tone(880,.08,{type:'triangle',vol:.05}); tone(1174,.14,{delay:.07,type:'triangle',vol:.05}); break;
      case 'buy': tone(330,.09,{vol:.05}); tone(440,.12,{delay:.08,vol:.05}); break;
      case 'place': tone(180,.1,{type:'sine',vol:.06,slide:120}); tone(320,.08,{delay:.05,vol:.04}); break;
      case 'error': tone(150,.16,{type:'sawtooth',vol:.04,slide:90}); break;
      case 'day': tone(392,.2,{vol:.025}); tone(587,.24,{delay:.1,vol:.02}); break;
      case 'fanfare': [523,659,784,1046].forEach((f,i)=>tone(f,.22,{delay:i*.1,vol:.05})); break;
      case 'goal': [659,784,988,1318].forEach((f,i)=>tone(f,.18,{delay:i*.07,type:'triangle',vol:.05})); break;
    }
  };
  const setMuted = v => { muted = v; localStorage.setItem('hydroharvest_muted', v?'1':'0'); updateMuteButtons(); };
  const toggle = () => setMuted(!muted);
  return { play, unlock, toggle, setMuted, isMuted:()=>muted };
})();
```

updateMuteButtons defined later (hoisted function).

State and helpers.

I need to be careful: `netWorth`, `fmtMoney` globals from data.js.

Write the file in one go. Let me draft mentally key functions and then write.

Important detail: `chargeUpkeep` uses `changeCash(-cost)` which triggers flash; if negative after, toast. `changeCash` will also call updateHUD; but during loop called at daily tick, fine.

`changeCash(amount)`:
```js
function changeCash(amount, opts={}) {
  state.cash += amount;
  updateHUD(); flashCash(amount >= 0 ? 1 : -1);
  if (amount < 0 && state.cash >= 0 && state.cash + (-amount) < 0) {} // nothing
}
```
Skip flash on tiny? Fine.

`updateHUD` also refresh goal mini text.

Money formatting: fmtMoney(-123) returns '−$123' using unicode minus. Good.

Emoji weather icons from WEATHERS.

`rollWeather` weighted; return key.

`generateOffer()`:
```js
const crop = CROPS[Math.floor(Math.random()*CROPS.length)];
const qty = Math.max(1, Math.round((1.5 + Math.random()*6) * (crop.yieldKg/1.4) * 2)/2);
const reward = Math.round(qty * crop.basePrice * (1.3 + Math.random()*0.25) * (0.85 + state.reputation*0.06));
