      <small>${bt.plants} sites · ${bt.spec.difficulty}${owned ? ' · ' + owned + ' owned' : ''}</small>
      <span class="sc-cost">${fmtMoney(bt.cost)}</span>
      ${id === best ? '<span class="lab-best">TOP MARGIN</span>' : ''}
