  const variants = sp.variants.map(v => `<span>${v}</span>`).join('');
  const tasks = bt.tasks.map(t => `<li>${t.label}${t.auto ? ' <em class="auto-tag">AUTO</em>' : ''}</li>`).join('');

  D.labSystems.innerHTML = `
    <div class="system-grid">${cards}</div>
    <div class="sys-detail">
      <div class="sys-detail-head">
        <div><small class="panel-kicker">SELECTED SYSTEM</small><h3>${bt.icon} ${bt.name}</h3></div>
        <div class="lab-best">${fmtMoney(bt.cost)} CAPEX</div>
      </div>
      <p>${sp.principle}</p>
      <div class="sys-spec">
        <div><small>FOOTPRINT</small><b>${sp.footprint}</b></div>
        <div><small>POWER / DAY</small><b>${sp.energy === 0 ? 'PASSIVE' : fmtPrice(sp.energy)}</b></div>
        <div><small>GROWTH SPEED</small><b>${Math.round(sp.growth * 100)}%</b></div>
        <div><small>WATER USE</small><b>${Math.round(sp.water * 100)}%</b></div>
        <div><small>PLANT SITES</small><b>${bt.plants}</b></div>
