      <div class="lab-section-title">Compatible crops</div>
      <div class="variant-chips">${bt.crops.map(cid => { const c = cropById(cid); return `<span>${c.icon} ${c.name} · ${c.cycleWeeks} wk</span>`; }).join('')}</div>
