    <p class="lab-note"><b>Reading this lab:</b> specs are real-world system trade-offs. Power is the daily electricity draw; growth speed multiplies crop development; water use scales reservoir consumption. The <b>Profitability</b> tab computes margin, payback and $/m²/week from these numbers and current market prices.</p>`;
}
function renderLabCycles() {
  const sys = lab.system;
  const bt = BED_TYPES[sys];
  if (!bt.crops.includes(lab.crop)) lab.crop = bt.crops[0];
  const crop = cropById(lab.crop);
  const sysChips = BED_IDS.map(id => `<button class="cycle-chip ${id === sys ? 'active' : ''}" data-sys="${id}">${BED_TYPES[id].icon} ${BED_TYPES[id].name}</button>`).join('');
  const cropChips = bt.crops.map(id => {
    const c = cropById(id);
    return `<button class="cycle-chip ${id === crop.id ? 'active' : ''}" data-crop="${id}">${c.icon} ${c.name}</button>`;
  }).join('');

  const rows = [];
  for (let week = 1; week <= crop.cycleWeeks; week++) {
    const base = bt.tasks.map(t => t.label);
    const extra = cropWeeklyTask(crop.id, week, crop.cycleWeeks);
    if (extra) base.push(extra);
    const pct = Math.round((week / crop.cycleWeeks) * 100);
    let stage = 'Seedling / establishment';
    if (week >= crop.cycleWeeks) stage = 'Harvest & reset';
    else if (pct >= 65) stage = crop.beds.includes('bucket') ? 'Flowering / fruiting' : 'Maturing';
    else if (pct >= 30) stage = crop.beds.includes('bucket') ? 'Vegetative / flowering' : 'Leafing out';
    const target = `pH 5.5–6.5 · EC ${crop.ec[0]}–${crop.ec[1]} mS/cm · ~${pct}% growth`;
    rows.push(`<tr>
      <td class="wk">WEEK ${week}<small>${week === 1 ? 'planting' : week === crop.cycleWeeks ? 'harvest week' : 'day ' + ((week - 1) * 7 + 1) + '–' + (week * 7)}</small></td>
      <td>${stage}</td>
