      <tbody>${rows.join('')}</tbody>
    </table></div>
    <p class="lab-note"><b>How to read the cycle:</b> every week repeats the system checks plus a crop-specific job (thinning, pruning, training, sanitising). Complete them from the bed panel; each task gives +health and a small growth boost. Week 1 is planting, the final week ends in harvest and system reset. <b>${bt.name}</b> runs ${bt.tasks.length} checks/week, ${bt.spec.energy === 0 ? 'uses no electricity' : `draws ${fmtPrice(bt.spec.energy)}/day of power`}.</p>`;
}
function renderLabProfit() {
  const start = state.stats.startDay || 1;
  const days = Math.max(1, state.day - start + 1);
  const actualRows = BED_IDS.map(id => {
    const bt = BED_TYPES[id];
    const rec = (state.stats.bySystem && state.stats.bySystem[id]) || { harvests: 0, kg: 0, revenue: 0, seedCost: 0, upkeep: 0, capex: 0 };
    const beds = state.beds.filter(b => b.type === id).length;
    const costs = rec.seedCost + rec.upkeep + rec.capex;
    const net = rec.revenue - costs;
    const roi = rec.capex > 0 ? (net / rec.capex) * 100 : 0;
    const perDay = net / days;
    const cls = net >= 0 ? 'profit-positive' : 'profit-negative';
    return `<tr>
      <td>${bt.icon} <b>${bt.name}</b><br><small style="color:var(--text-dim)">${beds} bed${beds === 1 ? '' : 's'}</small></td>
