313:   function plantMound(crop, growth, rng) {
314:     const g = new THREE.Group();
315:     const s = 0.42 + growth * 1.05;
316:     const bumps = growth > 0.55 ? 5 : 4;
317:     for (let i = 0; i < bumps; i++) {
318:       const r = (0.19 + rng() * 0.09) * s;
319:       const m = new THREE.Mesh(new THREE.IcosahedronGeometry(r, 0), leafMat(crop.leaf));
320:       const a = (i / bumps) * Math.PI * 2 + rng();
321:       m.position.set(Math.cos(a) * 0.16 * s, r * 0.75, Math.sin(a) * 0.16 * s);
322:       m.castShadow = true; g.add(m);
323:     }
324:     // crown sprout above
325:     const crown = new THREE.Mesh(new THREE.ConeGeometry(0.11 * s, 0.3 * s, 6), leafMat(crop.leaf));
326:     crown.position.y = 0.24 * s; g.add(crown);
327:     g.scale.setScalar(0.62 + growth * 0.95);
328:     return g;
329:   }
