331:   function fruitingPlant(crop, growth, rng) {
332:     const g = new THREE.Group();
333:     const stemH = 0.55 + growth * 1.15;
334:     const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.028, 0.036, stemH, 6), leafMat(0x4b7a3a));
335:     stem.position.y = stemH / 2; stem.castShadow = true; g.add(stem);
336:     // leaf clusters
337:     const clusters = 2 + Math.floor(growth * 3);
338:     for (let i = 0; i < clusters; i++) {
339:       const y = 0.35 + (i / clusters) * (stemH - 0.3);
340:       const leaf = new THREE.Mesh(new THREE.IcosahedronGeometry(0.13 + rng() * 0.06, 0), leafMat(crop.leaf));
341:       leaf.position.set((rng() - 0.5) * 0.24, y, (rng() - 0.5) * 0.24);
342:       leaf.scale.y = 0.7; g.add(leaf);
343:     }
344:     const fruits = [];
345:     if (crop.fruit && growth > 0.68) {
346:       const n = 2 + Math.floor((growth - 0.68) * 9);
347:       for (let i = 0; i < Math.min(5, n); i++) {
348:         const f = new THREE.Mesh(new THREE.SphereGeometry(0.075 + rng() * 0.02, 8, 6),
349:           new THREE.MeshLambertMaterial({ color: crop.fruit, emissive: crop.fruit, emissiveIntensity: 0.25 }));
350:         f.position.set((rng() - 0.5) * 0.4, 0.35 + rng() * (stemH - 0.35), (rng() - 0.5) * 0.4);
351:         f.castShadow = true; g.add(f); fruits.push(f);
352:       }
353:     }
354:     g.scale.setScalar(0.68 + growth * 0.8);
355:     return { group: g, fruits };
356:   }
