548:       seen.add(bed.id);
549:       const existing = bedMeshes.get(bed.id);
550:       const signature = JSON.stringify([bed.type, bed.cropId, Math.round((bed.growth || 0) * 24), Math.round(bed.health || 100)]);
551:       if (existing && existing.signature === signature) continue;
552:       if (existing) bedsGroup.remove(existing.group);
