cd /home/runner/work/PlayGround/PlayGround && python3 - <<'EOF'
p='js/world.js'
s=open(p).read()

# ── new module state ──
s=s.replace("  let bedsGroup, propsGroup, rainPoints, cloudsGroup, selectionRing, ghostGroup;\n",
"  let bedsGroup, propsGroup, rainPoints, cloudsGroup, selectionRing, ghostGroup;\n  let blueprintGroup, pipeGroup, pipes = [], flowDots = [];\n  let blueprintOn = true;\n  let preview = null;\n")

# ── build blueprint after greenhouse/props ──
s=s.replace("    buildGround();\n    buildGreenhouse();\n    buildProps();",
"    buildGround();\n    buildBlueprint();\n    buildGreenhouse();\n    buildProps();")

# ── add text sprite + blueprint functions after labelSprite ──
anchor = "  /* ─────────── GROUND & GREENHOUSE ─────────── */"
newfns = r'''  function textSprite(lines, opts) {
    opts = opts || {};
    const pad = 14, lh = 34, fs = opts.fontSize || 26;
    const c = document.createElement('canvas');
    const ctx = c.getContext('2d');
    ctx.font = `700 ${fs}px "Segoe UI", Arial, sans-serif`;
    let maxW = 0;
    for (const line of lines) maxW = Math.max(maxW, ctx.measureText(line).width);
    c.width = Math.ceil(maxW + pad * 2);
    c.height = lh * lines.length + pad * 2;
    const g = c.getContext('2d');
    g.fillStyle = opts.bg || 'rgba(5,16,12,.88)';
    g.strokeStyle = opts.border || '#38d6e0';
    g.lineWidth = 3;
    const r = 9;
    const W = c.width, H = c.height;
    g.beginPath();
    g.moveTo(r, 0); g.lineTo(W - r, 0); g.quadraticCurveTo(W, 0, W, r);
