function cashChartSVG() {
  const arr = (state.history && state.history.cash ? state.history.cash : []).slice(-40);
  if (arr.length < 2) return '<div class="chart-empty">La línea de caja aparece después de tu primer día completo.<br>Mientras tanto, mirá la caja actual y el costo fijo diario en las tarjetas de arriba.</div>';
  const W=600,H=168,padL=44,padR=12,padT=16,padB=20;
  const vals = arr.map(p=>p.value);
  let min = Math.min(...vals), max = Math.max(...vals);
  if (max-min < 1) { max += 50; min -= 50; }
  const span = max-min;
  const x = i => padL + (i/(arr.length-1))*(W-padL-padR);
  const y = v => padT + (1-(v-min)/span)*(H-padT-padB);
