const { chromium } = require('playwright-core');
const path = '/home/runner/.cache/ms-playwright/chromium-1254/chrome-linux64/chrome';
const BASE = 'http://localhost:3002/';
const OUT = '/home/runner/work/PlayGround/PlayGround/screenshots';

(async () => {
  const browser = await chromium.launch({ executablePath: path, args: ['--no-sandbox'] });
  const errors = [];
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  const page = await ctx.newPage();
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  await page.goto(BASE, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1200);
  await page.screenshot({ path: OUT + '/desktop-title.jpg', type: 'jpeg', quality: 62 });
  await page.click('#btn-start-build');
  await page.waitForTimeout(1600);
  await page.screenshot({ path: OUT + '/desktop-start.jpg', type: 'jpeg', quality: 62 });

  // dashboard
  await page.click('#btn-dashboard');
  await page.waitForTimeout(500);
  await page.screenshot({ path: OUT + '/desktop-dashboard.jpg', type: 'jpeg', quality: 62 });
  const dash = await page.evaluate(() => ({
    kpis: document.querySelectorAll('#dash-kpis .dash-kpi').length,
    cashSvg: !!document.querySelector('#dash-cash svg'),
    harvestBox: document.querySelector('#dash-harvest')?.textContent.trim().slice(0, 60),
    ganttRows: document.querySelectorAll('#dash-gantt .gantt-row').length,
    events: document.querySelectorAll('#dash-events .event-item').length,
  }));
  console.log('DASH', JSON.stringify(dash));
  await page.keyboard.press('Escape');

  // advisor
  await page.click('#btn-advisor');
  await page.waitForTimeout(700);
  await page.screenshot({ path: OUT + '/desktop-advisor.jpg', type: 'jpeg', quality: 62 });
  const adv = await page.evaluate(() => ({
    kpis: document.querySelectorAll('#advisor-kpis .dash-kpi').length,
    messages: document.querySelectorAll('#advisor-log .adv-msg').length,
    budgetText: document.querySelector('#advisor-budget-result')?.innerText.slice(0, 120),
    options: [document.querySelector('#adv-greenhouse')?.options.length, document.querySelector('#adv-system')?.options.length],
  }));
  console.log('ADVISOR', JSON.stringify(adv));
  await page.click('#advisor-chips [data-q="¿Qué sistema me conviene?"]');
  await page.waitForTimeout(300);
  await page.fill('#advisor-input', '¿Cuánta agua consume la granja?');
  await page.press('#advisor-input', 'Enter');
  await page.waitForTimeout(300);
  await page.click('#adv-explain');
  await page.waitForTimeout(300);
  await page.screenshot({ path: OUT + '/desktop-advisor-chat.jpg', type: 'jpeg', quality: 62 });
  const msgCount = await page.evaluate(() => document.querySelectorAll('#advisor-log .adv-msg').length);
  console.log('ADVISOR_MESSAGES', msgCount);
  await page.keyboard.press('Escape');

  // lab systems + preview canvas
  await page.click('#btn-systems');
  await page.waitForTimeout(1000);
  await page.screenshot({ path: OUT + '/desktop-lab-systems.jpg', type: 'jpeg', quality: 62 });
  const lab = await page.evaluate(() => ({
    cards: document.querySelectorAll('#lab-systems .system-card').length,
    previewCanvas: !!document.querySelector('#lab-preview canvas'),
    bomRows: document.querySelectorAll('#lab-systems .bom-table tbody tr').length,
    waterStages: document.querySelectorAll('#lab-systems .wc-stage').length,
    text: document.querySelector('#lab-systems .layout-equation')?.innerText.replace(/\s+/g, ' '),
  }));
  console.log('LAB', JSON.stringify(lab));
  await page.click('[data-labtab="timeline"]');
  await page.waitForTimeout(400);
  await page.screenshot({ path: OUT + '/desktop-lab-timeline.jpg', type: 'jpeg', quality: 62 });
  const tl = await page.evaluate(() => ({
    svg: !!document.querySelector('#lab-timeline svg'),
    ganttRows: document.querySelectorAll('#lab-timeline .gantt-row').length,
  }));
  console.log('TIMELINE', JSON.stringify(tl));
  await page.click('[data-labtab="greenhouses"]');
  await page.waitForTimeout(400);
  await page.screenshot({ path: OUT + '/desktop-greenhouses.jpg', type: 'jpeg', quality: 62 });
  const gh = await page.evaluate(() => ({
    cards: document.querySelectorAll('#lab-greenhouses .gh-card').length,
    plans: document.querySelectorAll('#lab-greenhouses .gh-plan svg').length,
  }));
  console.log('GREENHOUSES', JSON.stringify(gh));
  await page.click('[data-quote="multitunel"]');
  await page.waitForTimeout(500);
  const advFromGh = await page.evaluate(() => ({
    modal: !document.querySelector('#modal-advisor').classList.contains('hidden'),
    gh: document.querySelector('#adv-greenhouse').value,
    budget: document.querySelector('#advisor-budget-result')?.innerText.slice(0, 80),
  }));
  console.log('ADV_FROM_GH', JSON.stringify(advFromGh));
  await page.keyboard.press('Escape');

  // blueprint toggle
  await page.click('#btn-blueprint');
  await page.waitForTimeout(300);
  const bpOff = await page.evaluate(() => ({ state: state.blueprint, legend: document.querySelector('#bp-legend').classList.contains('hidden'), btnActive: document.querySelector('#btn-blueprint').classList.contains('active') }));
  await page.click('#btn-blueprint');
  await page.waitForTimeout(300);
  const bpOn = await page.evaluate(() => ({ state: state.blueprint, legend: document.querySelector('#bp-legend').classList.contains('hidden'), btnActive: document.querySelector('#btn-blueprint').classList.contains('active') }));
  console.log('BLUEPRINT', JSON.stringify({ bpOff, bpOn }));
  await page.screenshot({ path: OUT + '/desktop-blueprint.jpg', type: 'jpeg', quality: 62 });

  // god mode through menu
  await page.click('#btn-menu');
  await page.waitForTimeout(300);
  await page.click('#menu-god');
  await page.waitForTimeout(700);
  const god = await page.evaluate(() => ({ god: state.godMode, cash: document.querySelector('#cash-label').textContent, badge: !document.querySelector('#god-badge').classList.contains('hidden') }));
  console.log('GOD', JSON.stringify(god));
  await page.screenshot({ path: OUT + '/desktop-god.jpg', type: 'jpeg', quality: 62 });

  // camera buttons
  const beforeCam = await page.evaluate(() => World.screenPos(0, 0, 0));
  await page.click('#cam-right');
  await page.waitForTimeout(500);
  const afterCam = await page.evaluate(() => World.screenPos(0, 0, 0));
  console.log('CAMERA', JSON.stringify({ beforeCam, afterCam }));

  console.log('ERRORS', JSON.stringify(errors));
  await browser.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });

