    const card = document.querySelector('#modal-systems .modal-card');
    const cr = card.getBoundingClientRect();
    const out = [];
    card.querySelectorAll('*').forEach(el => {
      const r = el.getBoundingClientRect();
      const cs = getComputedStyle(el);
      if (r.width > cr.width + 4 || r.right > cr.right + 4 || el.scrollWidth > el.clientWidth + 4) {
        out.push({ tag: el.tagName, cls: el.className && String(el.className).slice(0, 50), id: el.id, w: Math.round(r.width), right: Math.round(r.right), sw: el.scrollWidth, cw: el.clientWidth, ov: cs.overflowX, minW: cs.minWidth });
      }
    });
    return { card: { w: Math.round(cr.width), sw: card.scrollWidth }, items: out.slice(0, 40) };
  });
  console.log(JSON.stringify(audit, null, 1));
  const pv = await page.evaluate(() => {
    const h = document.querySelector('#lab-preview'); const c = h?.querySelector('canvas');
    return { hostW: h?.clientWidth, hostH: h?.clientHeight, canvasW: c?.width, canvasH: c?.height, canvasCssW: c?.style.width, canvasCssH: c?.style.height, hostRectW: h?.getBoundingClientRect().width };
