    await page.keyboard.press('Escape');

    // harvest + sell + advance for charts
    await page.evaluate(() => { const b = state.beds[0]; b.growth = 1; b.health = 100; refreshWorld(); selectBed(b.id); });
    await page.waitForTimeout(300);
    await page.click('#btn-harvest');
    await page.waitForTimeout(500);
    await page.evaluate(() => { sellAll(); advanceDay(); });
    await page.waitForTimeout(500);
