function updateProjection() {
  const aspect = window.innerWidth / window.innerHeight;
  const h = cam.dist;
  const w = h * aspect;
  camera.left = -w / 2; camera.right = w / 2;
  camera.top = h / 2; camera.bottom = -h / 2;
