const { chromium } = require('playwright-core');
const CHROME = '/home/runner/.cache/ms-playwright/chromium-1254/chrome-linux64/chrome';

(async () => {
  const browser = await chromium.launch({ executablePath: CHROME, args: ['--no-sandbox', '--disable-dev-shm-usage'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));

  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(600);
  await page.screenshot({ path: 'screenshots/desktop-title.png' });

  await page.click('[data-build="leafy"]');
  await page.click('#btn-start-build');
  await page.waitForTimeout(1400);
  await page.screenshot({ path: 'screenshots/desktop-main.png' });

  const hud = await page.evaluate(() => ({
    cash: document.querySelector('#cash-label').textContent,
    net: document.querySelector('#networth-label').textContent,
    overview: !document.querySelector('#hud').classList.contains('hidden-until-start'),
    canvas: !!document.querySelector('#scene'),
  }));

  await page.click('#btn-dashboard');
  await page.waitForTimeout(700);
