const { chromium } = require('playwright-core');
const CHROME = '/home/runner/.cache/ms-playwright/chromium-1254/chrome-linux64/chrome';

(async () => {
  const browser = await chromium.launch({ executablePath: CHROME, args: ['--no-sandbox', '--disable-dev-shm-usage'] });
  const context = await browser.newContext({
    viewport: { width: 390, height: 844 },
    deviceScaleFactor: 2,
    isMobile: true,
    hasTouch: true,
    userAgent: 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1',
  });
  const page = await context.newPage();
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));

  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(700);
  await page.screenshot({ path: 'screenshots/mobile-title.png' });

  await page.tap('[data-build="sandbox"]');
  await page.tap('#btn-start-build');
  await page.waitForTimeout(1200);
  await page.screenshot({ path: 'screenshots/mobile-main.png' });

  const main = await page.evaluate(() => {
    const nav = document.querySelector('#mobile-nav');
    const nr = nav.getBoundingClientRect();
    return {
      overflowX: document.documentElement.scrollWidth > window.innerWidth + 1,
      scrollWidth: document.documentElement.scrollWidth,
      navVisible: !nav.classList.contains('hidden-until-start') && nr.bottom <= window.innerHeight + 1,
      navButtons: nav.querySelectorAll('button').length,
      cash: document.querySelector('#cash-label').textContent,
      goalVisible: document.querySelector('#goals-mini').getBoundingClientRect().bottom < nr.top,
    };
  });

  await page.tap('[data-mobile="dashboard"]');
  await page.waitForTimeout(700);
  await page.screenshot({ path: 'screenshots/mobile-dashboard.png' });
  const dash = await page.evaluate(() => {
    const card = document.querySelector('#modal-dashboard .dash-card');
    return {
      open: !document.querySelector('#modal-dashboard').classList.contains('hidden'),
      overflow: card.scrollWidth > card.clientWidth + 1,
      charts: document.querySelectorAll('#dash-cash svg, #dash-harvest svg').length,
      ganttScroll: document.querySelector('#dash-gantt').scrollWidth > document.querySelector('#dash-gantt').clientWidth,
      cardsVisible: document.querySelectorAll('#dash-dashboard, .dash-kpi').length,
    };
  });
  await page.tap('#modal-dashboard [data-close-modal]');

  await page.tap('[data-mobile="advisor"]');
  await page.waitForTimeout(700);
  await page.screenshot({ path: 'screenshots/mobile-advisor.png' });
  const adv = await page.evaluate(() => {
    const card = document.querySelector('.advisor-card');
    return {
      beds: document.querySelector('#adv-beds').value,
      verdict: document.querySelector('#advisor-budget-result .budget-callout')?.textContent.trim().slice(0, 90),
      overflow: card.scrollWidth > card.clientWidth + 1,
      budgetTop: Math.round(document.querySelector('#advisor-budget-result').getBoundingClientRect().top),
    };
  });
  await page.tap('#modal-advisor [data-close-modal]');

  await page.tap('[data-mobile="systems"]');
  await page.waitForTimeout(1000);
  await page.screenshot({ path: 'screenshots/mobile-lab.png' });
  const lab = await page.evaluate(() => {
    const card = document.querySelector('.lab-card');
    const canvas = document.querySelector('#lab-systems canvas');
    const host = canvas ? canvas.parentElement.getBoundingClientRect() : null;
    return {
      open: !document.querySelector('#modal-systems').classList.contains('hidden'),
      tabs: document.querySelectorAll('#lab-tabs .lab-tab').length,
      tabsRows: new Set([...document.querySelectorAll('#lab-tabs .lab-tab')].map(e => Math.round(e.getBoundingClientRect().top))).size,
      preview: canvas ? { w: Math.round(host.width), h: Math.round(host.height), canvasW: canvas.width } : null,
      overflow: card.scrollWidth > card.clientWidth + 1,
    };
  });
  await page.tap('[data-labtab="greenhouses"]');
  await page.waitForTimeout(400);
  await page.screenshot({ path: 'screenshots/mobile-greenhouses.png' });
  await page.tap('#modal-systems [data-close-modal]');

  // open a bed panel programmatically (top-level global function)
  const bedTest = await page.evaluate(() => {
    try {
      const id = typeof state !== 'undefined' && state.beds && state.beds[0] ? state.beds[0].id : null;
      if (id && typeof selectBed === 'function') { selectBed(id); return { ok: true, id }; }
      return { ok: false, hasState: typeof state, hasSelect: typeof selectBed };
    } catch (e) { return { ok: false, err: e.message }; }
  });
  await page.waitForTimeout(500);
  await page.screenshot({ path: 'screenshots/mobile-bed.png' });

  console.log(JSON.stringify({ main, dash, adv, lab, bedTest, errors }, null, 2));
  await browser.close();
})();

