const { chromium } = require('playwright-core');
const CHROME = '/home/runner/.cache/ms-playwright/chromium-1254/chrome-linux64/chrome';

(async () => {
  const browser = await chromium.launch({ executablePath: CHROME, args: ['--no-sandbox', '--disable-dev-shm-usage'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(400);
  await page.click('[data-build="leafy"]');
  await page.click('#btn-start-build');
  await page.waitForTimeout(900);

  const prep = await page.evaluate(() => {
    const bed = state.beds[0];
    bed.growth = 1; bed.health = 100;
    selectBed(bed.id);
    return { id: bed.id, crop: bed.cropId, ph: document.querySelector('#ph-label').textContent, ec: document.querySelector('#ec-label').textContent, btn: document.querySelector('#btn-harvest').textContent, disabled: document.querySelector('#btn-harvest').disabled };
  });
  await page.waitForTimeout(300);
  await page.screenshot({ path: 'screenshots/desktop-bed-ready.png' });
  await page.click('#btn-harvest');
  await page.waitForTimeout(500);
  const harvest = await page.evaluate(() => ({
    toast: document.querySelector('#toasts .toast')?.textContent,
    stock: state.inventory.lettuce,
    harvests: state.history.harvests.length,
  }));
  await page.screenshot({ path: 'screenshots/desktop-harvest.png' });

  await page.click('#btn-market');
  await page.waitForTimeout(400);
  const market = await page.evaluate(() => ({
    stockText: document.querySelector('#market-rows .m-stock')?.textContent,
    value: document.querySelector('#market-inventory-value')?.textContent,
  }));
  await page.click('#market-sell-all');
  await page.waitForTimeout(500);
  const sale = await page.evaluate(() => ({
    toast: document.querySelector('#toasts .toast')?.textContent,
    cash: document.querySelector('#cash-label').textContent,
    invValue: document.querySelector('#market-inventory-value')?.textContent,
  }));
  await page.screenshot({ path: 'screenshots/desktop-sale.png' });
  await page.click('#modal-market [data-close-modal]');
  await page.click('#btn-dashboard');
  await page.waitForTimeout(500);
  const dash = await page.evaluate(() => ({
